#!/usr/bin/env python3
"""Embed plugin/web/index.html into plugin/src/WebPage.h (split into <8 KB literals; MSVC limit is 16 KB)."""
import pathlib
root = pathlib.Path(__file__).resolve().parent.parent
html = (root / "plugin/web/index.html").read_bytes().decode("utf-8")
assert ")SC4WEB\"" not in html
chunks = [html[i:i + 6000] for i in range(0, len(html), 6000)]
body = "\n".join('    R"SC4WEB(' + c + ')SC4WEB"' for c in chunks)
(root / "plugin/src/WebPage.h").write_text(
    "// GENERATED by tools/gen_webpage.py from plugin/web/index.html. Do not edit.\n"
    "#pragma once\nstatic const char* const kWebPage =\n" + body + ";\n", encoding="utf-8")
print("chunks:", len(chunks), "bytes:", len(html.encode()))
